param([Parameter(Mandatory=$true)][string]$PackageRoot,[ValidateSet('Upgrade','FreshHost','FreshEmployee','Recover','RecoverStart','Bridge','EmployeeSlot','EmployeeSlotRecover')][string]$Action='Upgrade')
$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
Add-Type -AssemblyName System.Windows.Forms
# Fixed data-free path/FD guard shared by the two reviewed native launchers.
Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.Text;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
public static class XjyInitialPathGuard {
 [StructLayout(LayoutKind.Sequential)] struct Info { public uint attributes; public uint creationLow; public uint creationHigh; public uint accessLow; public uint accessHigh; public uint writeLow; public uint writeHigh; public uint volume; public uint sizeHigh; public uint sizeLow; public uint links; public uint indexHigh; public uint indexLow; }
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileInformationByHandle(SafeFileHandle h,out Info info);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern uint GetFinalPathNameByHandle(SafeFileHandle h,StringBuilder value,uint size,uint flags);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern SafeFileHandle CreateFileW(string path,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
 public static void Check(SafeFileHandle handle,string expected,bool directory) { Info info;if(!GetFileInformationByHandle(handle,out info))throw new IOException("Cannot inspect fixed handle");if((info.attributes&0x400)!=0||(directory?(info.attributes&0x10)==0:(info.attributes&0x10)!=0||info.links!=1))throw new IOException("Link or unexpected file identity");var text=new StringBuilder(32768);uint n=GetFinalPathNameByHandle(handle,text,32768,0);if(n==0||n>=32768)throw new IOException("Cannot canonicalize handle");string actual=text.ToString();if(actual.StartsWith(@"\\?\"))actual=actual.Substring(4);if(!String.Equals(Path.GetFullPath(expected),actual,StringComparison.OrdinalIgnoreCase))throw new IOException("Path changed or alias used"); }
 public static SafeFileHandle Directory(string name) { var h=CreateFileW(name,0x80,1,IntPtr.Zero,3,0x02000000,IntPtr.Zero);if(h.IsInvalid)throw new IOException("Cannot pin fixed directory");try{Check(h,name,true);return h;}catch{h.Dispose();throw;} }
}
'@
function Pin-PlainFile([string]$Name) { $f=[IO.File]::Open($Name,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{[XjyInitialPathGuard]::Check($f.SafeFileHandle,$Name,$false);return $f}catch{$f.Dispose();throw} }
function Pin-PlainDirectory([string]$Name) { return [XjyInitialPathGuard]::Directory($Name) }

<#
  鑫金源珠宝 1.7.0 电脑版 · 一键安装进度视图（Windows PowerShell 5.1 / WinForms 草稿）
  仅视图层，不含安装、签名、恢复等逻辑。本文件请保存为 UTF-8（带 BOM），5.1 才能正确读取中文。
  用法：$v = New-XjyProgressView；$v.Form.Show()；循环中 Set-XjyProgressView -View $v [-Stage ..] [-Detail ..] [-Percent 0..100]；
        结束后必须调用 Close-XjyProgressView -View $v（内部先置 AllowedClose，再释放窗体）。
  未知总量或非法百分比只显示不确定动画，绝不伪造百分比；运行中用户点关闭仅最小化，不终止安装。
#>
function New-XjyProgressView {
    [CmdletBinding()]
    param(
        [string]$Stage = '正在检查新版本，请稍候…',
        [string]$Detail = '请保持本窗口打开；如提示需要退出，请从右下角托盘正常退出。'
    )
    Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop
    Add-Type -AssemblyName System.Drawing -ErrorAction Stop
    $ivory = [System.Drawing.Color]::FromArgb(252, 249, 243); $wine = [System.Drawing.Color]::FromArgb(122, 31, 43); $ink = [System.Drawing.Color]::FromArgb(53, 50, 46)
    $form = New-Object System.Windows.Forms.Form
    $form.Text = '鑫金源珠宝 1.7.0 电脑版 · 升级'
    $form.ClientSize = New-Object System.Drawing.Size -ArgumentList 520, 230
    $form.StartPosition = [System.Windows.Forms.FormStartPosition]::CenterScreen
    $form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedSingle
    $form.MaximizeBox = $false; $form.MinimizeBox = $true; $form.ShowInTaskbar = $true
    $form.BackColor = $ivory; $form.AutoScaleMode = [System.Windows.Forms.AutoScaleMode]::Dpi
    $form.AutoScaleDimensions = New-Object System.Drawing.SizeF -ArgumentList 96, 96
    $form.Tag = @{ AllowedClose = $false }
    $fontTitle = New-Object System.Drawing.Font -ArgumentList 'Microsoft YaHei', ([float]15.0), ([System.Drawing.FontStyle]::Bold), ([System.Drawing.GraphicsUnit]::Point)
    $fontDetail = New-Object System.Drawing.Font -ArgumentList 'Microsoft YaHei', ([float]10.5), ([System.Drawing.FontStyle]::Regular), ([System.Drawing.GraphicsUnit]::Point)
    $form.Tag.Fonts = @($fontTitle, $fontDetail)
    $titleLabel = New-Object System.Windows.Forms.Label
    $titleLabel.Text = $Stage; $titleLabel.ForeColor = $wine; $titleLabel.Font = $fontTitle
    $titleLabel.AutoSize = $false; $titleLabel.TextAlign = [System.Drawing.ContentAlignment]::MiddleLeft
    $titleLabel.Location = New-Object System.Drawing.Point -ArgumentList 20, 24
    $titleLabel.Size = New-Object System.Drawing.Size -ArgumentList 480, 40
    $detailLabel = New-Object System.Windows.Forms.Label
    $detailLabel.Text = $Detail; $detailLabel.ForeColor = $ink; $detailLabel.Font = $fontDetail; $detailLabel.AutoSize = $false
    $detailLabel.Location = New-Object System.Drawing.Point -ArgumentList 20, 76
    $detailLabel.Size = New-Object System.Drawing.Size -ArgumentList 480, 64
    $bar = New-Object System.Windows.Forms.ProgressBar
    $bar.Minimum = 0; $bar.Maximum = 100; $bar.MarqueeAnimationSpeed = 30
    $bar.Style = [System.Windows.Forms.ProgressBarStyle]::Marquee
    $bar.Location = New-Object System.Drawing.Point -ArgumentList 20, 168
    $bar.Size = New-Object System.Drawing.Size -ArgumentList 480, 22
    $form.Controls.AddRange(@($titleLabel, $detailLabel, $bar))
    $form.add_FormClosing({
        param($sender, $eventArgs)
        $state = $sender.Tag
        if ($null -ne $state -and -not $state.AllowedClose) { $eventArgs.Cancel = $true; $sender.WindowState = [System.Windows.Forms.FormWindowState]::Minimized }
    })
    [pscustomobject]@{ Form = $form; TitleLabel = $titleLabel; DetailLabel = $detailLabel; ProgressBar = $bar }
}

function Set-XjyProgressView {
    [CmdletBinding()]
    param(
        [Parameter(Position = 0)][PSObject]$View,
        [string]$Stage,
        [string]$Detail,
        [object]$Percent = $null
    )
    if ($null -eq $View) { return }
    $form = $View.Form
    if ($null -eq $form -or $form.IsDisposed) { return }
    $percentValue = -1
    if ($null -ne $Percent) {
        $parsed = 0
        if ([int]::TryParse([string]$Percent, [ref]$parsed) -and $parsed -ge 0 -and $parsed -le 100) { $percentValue = $parsed }
    }
    try {
        if (-not [string]::IsNullOrWhiteSpace($Stage)) { $View.TitleLabel.Text = $Stage }
        if (-not [string]::IsNullOrWhiteSpace($Detail)) { $View.DetailLabel.Text = $Detail }
        if ($percentValue -ge 0) {
            $View.ProgressBar.Style = [System.Windows.Forms.ProgressBarStyle]::Continuous
            $View.ProgressBar.Value = $percentValue
        } else {
            $View.ProgressBar.Style = [System.Windows.Forms.ProgressBarStyle]::Marquee
        }
        if ($form.Visible) { [System.Windows.Forms.Application]::DoEvents() }
    } catch {
        # 已 Dispose 或控件更新失败：静默返回，不伪造任何状态
    }
}

function Close-XjyProgressView {
    [CmdletBinding()]
    param([Parameter(Position = 0)][PSObject]$View)
    if ($null -eq $View) { return }
    $form = $View.Form
    if ($null -eq $form) { return }
    $state = $form.Tag
    if ($state -is [hashtable]) { $state.AllowedClose = $true }
    if (-not $form.IsDisposed) {
        try { $form.Close() } catch { }
        try { if (-not $form.IsDisposed) { $form.Dispose() } } catch { }
        foreach ($ownedFont in $state.Fonts) { if ($null -ne $ownedFont) { $ownedFont.Dispose() } }
        $state.Fonts = @()
    }
}
$progressView=$null
$held=New-Object 'Collections.Generic.List[IDisposable]'
$dirs=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
function Hold-Parents([string]$Name){$p=$Name;while($p){if($dirs.Add($p)){$held.Add((Pin-PlainDirectory $p))};$parent=[IO.Directory]::GetParent($p);if(!$parent){break};$p=$parent.FullName}}
function File-Hash($Stream){$Stream.Position=0;$h=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($h.ComputeHash($Stream))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function Quote-Arg([string]$Value){if($Value.Contains('"') -or $Value.Contains("`r") -or $Value.Contains("`n")){throw '参数含不允许的字符。'};return '"'+$Value+'"'}
function Initialize-XjyEmployeeShortcutIo {
 if('XjyEmployeeShortcutIo' -as [type]){return}
 Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
public static class XjyEmployeeShortcutIo {
 [StructLayout(LayoutKind.Sequential)] struct Info { public uint attributes; public uint creationLow; public uint creationHigh; public uint accessLow; public uint accessHigh; public uint writeLow; public uint writeHigh; public uint volume; public uint sizeHigh; public uint sizeLow; public uint links; public uint indexHigh; public uint indexLow; }
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct Rename { [MarshalAs(UnmanagedType.U1)] public bool replace; public IntPtr root; public uint length; public char name; }
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileInformationByHandle(SafeFileHandle handle,out Info info);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern uint GetFinalPathNameByHandle(SafeFileHandle handle,StringBuilder value,uint size,uint flags);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern SafeFileHandle CreateFileW(string path,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool SetFileInformationByHandle(SafeFileHandle handle,int kind,IntPtr info,uint size);
 static Info Read(SafeFileHandle handle) { Info i;if(!GetFileInformationByHandle(handle,out i))throw new IOException("SHORTCUT_IDENTITY_WIN32_"+Marshal.GetLastWin32Error());return i; }
 public static string Identity(SafeFileHandle handle) { var i=Read(handle);return i.volume.ToString("x8")+":"+(((ulong)i.indexHigh<<32)|i.indexLow).ToString("x16"); }
 public static SafeFileHandle Reserve(string path) {
  // CREATE_NEW: never claim an orphan. Attributes-only access lets COM save
  // into our file while omission of FILE_SHARE_DELETE prevents replacement.
  var h=CreateFileW(path,0x80,3,IntPtr.Zero,1,0x80,IntPtr.Zero);
  if(h.IsInvalid){h.Dispose();throw new IOException("SHORTCUT_TEMP_CREATE_NEW_"+Marshal.GetLastWin32Error());}return h;
 }
 public static void Publish(string source,string target,string expectedIdentity,string expectedSha256) {
  var h=CreateFileW(source,0x10081,1,IntPtr.Zero,3,0,IntPtr.Zero);
  if(h.IsInvalid){h.Dispose();throw new IOException("SHORTCUT_OWNED_OPEN_"+Marshal.GetLastWin32Error());}
  try {var i=Read(h);if((i.attributes&0x410)!=0||i.links!=1||Identity(h)!=expectedIdentity)throw new IOException("SHORTCUT_TEMP_IDENTITY_CHANGED");
   using(var borrowed=new SafeFileHandle(h.DangerousGetHandle(),false))using(var stream=new FileStream(borrowed,FileAccess.Read))using(var sha=SHA256.Create())if(BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant()!=expectedSha256)throw new IOException("SHORTCUT_TEMP_BYTES_CHANGED");
    var fullTarget=Path.GetFullPath(target);var bytes=Encoding.Unicode.GetBytes(fullTarget);int offset=(int)Marshal.OffsetOf(typeof(Rename),"name");int bufferSize=offset+bytes.Length+2;var buffer=Marshal.AllocHGlobal(bufferSize);
   try {for(int n=0;n<bufferSize;n++)Marshal.WriteByte(buffer,n,0);Marshal.WriteInt32(buffer,(int)Marshal.OffsetOf(typeof(Rename),"length"),bytes.Length);Marshal.Copy(bytes,0,IntPtr.Add(buffer,offset),bytes.Length);
    // FileRenameInfo, ReplaceIfExists=false: a competing final LNK survives.
    // Keep FileNameLength in bytes excluding NUL, but fully zero and terminate
    // FileName: the observed Win32 path conversion read past an unterminated
    // name into heap tail characters, bypassing the intended final basename.
    if(!SetFileInformationByHandle(h,3,buffer,(uint)bufferSize))throw new IOException("SHORTCUT_PUBLISH_NO_REPLACE_"+Marshal.GetLastWin32Error());
    if(Identity(h)!=expectedIdentity)throw new IOException("SHORTCUT_PUBLISH_IDENTITY_CHANGED");
    var finalName=new StringBuilder(32768);uint actualLength=GetFinalPathNameByHandle(h,finalName,32768,0);if(actualLength==0||actualLength>=32768)throw new IOException("SHORTCUT_PUBLISH_PATH_UNREADABLE");string actual=finalName.ToString();if(actual.StartsWith(@"\\?\"))actual=actual.Substring(4);if(!String.Equals(Path.GetFullPath(actual),fullTarget,StringComparison.OrdinalIgnoreCase))throw new IOException("SHORTCUT_PUBLISH_PATH_CHANGED: "+actual);
   }finally{Marshal.FreeHGlobal(buffer);}
  }finally{h.Dispose();}
 }
}
'@
}
function Hold-XjyEmployeeShortcutParents([string]$Directory,$Pins){
 $walk=[IO.Path]::GetFullPath($Directory)
 while($walk){$pin=Pin-PlainDirectory $walk;$Pins.Add($pin);$parent=[IO.Directory]::GetParent($walk);if(!$parent){break};$walk=$parent.FullName}
}
function Assert-XjyEmployeeLink($Shell,[string]$Path,[string]$Exe,[string]$Install){
 $link=$Shell.CreateShortcut($Path)
 try{if(![StringComparer]::OrdinalIgnoreCase.Equals([IO.Path]::GetFullPath([string]$link.TargetPath),$Exe) -or [string]$link.Arguments -cne '--employee-client' -or ![StringComparer]::OrdinalIgnoreCase.Equals([IO.Path]::GetFullPath([string]$link.WorkingDirectory),$Install)){throw 'SHORTCUT_CONFLICT：同名员工快捷方式不属于本次已验证程序，未覆盖。'}}finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($link)}
}
function Ensure-XjyEmployeeShortcut([string]$InstallationDir,[string]$DesktopDirectory=''){
 Initialize-XjyEmployeeShortcutIo
 if(!$InstallationDir -or ![IO.Path]::IsPathRooted($InstallationDir) -or $InstallationDir.StartsWith('\\') -or $InstallationDir.Substring(2).Contains(':')){throw '员工快捷方式安装目录无效。'}
 $install=[IO.Path]::GetFullPath($InstallationDir);$targetExe=Join-Path $install '鑫金源珠宝报价.exe'
 # DesktopDirectory is explicit test DI only. Shipping caller omits it and
 # obtains current user's KnownFolder; it is not a PS/CMD/renderer parameter.
 $desktop=if($DesktopDirectory){[IO.Path]::GetFullPath($DesktopDirectory)}else{[Environment]::GetFolderPath([Environment+SpecialFolder]::DesktopDirectory)}
 if(!$desktop -or $desktop.StartsWith('\\') -or $desktop.Substring(2).Contains(':')){throw '员工桌面KnownFolder不是普通本机目录。'}
 $pins=New-Object 'Collections.Generic.List[IDisposable]';$shell=$null;$reservation=$null
 try{
  Hold-XjyEmployeeShortcutParents $install $pins;Hold-XjyEmployeeShortcutParents $desktop $pins
  $exePin=Pin-PlainFile $targetExe;$pins.Add($exePin)
  $desktopPin=Pin-PlainDirectory $desktop;$pins.Add($desktopPin);$desktopIdentity=[XjyEmployeeShortcutIo]::Identity($desktopPin)
  $path=Join-Path $desktop '鑫金源珠宝（员工端）.lnk';$shell=New-Object -ComObject WScript.Shell
  if(Test-Path -LiteralPath $path){$existing=Pin-PlainFile $path;$pins.Add($existing);Assert-XjyEmployeeLink $shell $path $targetExe $install;[XjyInitialPathGuard]::Check($existing.SafeFileHandle,$path,$false);return [pscustomobject]@{created=$false;reused=$true;path=$path}}
  $temp=Join-Path $desktop ('.xjy-employee-shortcut-'+[Guid]::NewGuid().ToString('D')+'.lnk')
  # Build the COM object before reserving an empty file. CREATE_NEW below
  # owns its exact identity before Save can write, never opens an old orphan.
  $newLink=$shell.CreateShortcut($temp)
  try{$newLink.TargetPath=$targetExe;$newLink.Arguments='--employee-client';$newLink.WorkingDirectory=$install
   $reservation=[XjyEmployeeShortcutIo]::Reserve($temp);[XjyInitialPathGuard]::Check($reservation,$temp,$false);$identity=[XjyEmployeeShortcutIo]::Identity($reservation)
   $newLink.Save();[XjyInitialPathGuard]::Check($reservation,$temp,$false);if([XjyEmployeeShortcutIo]::Identity($reservation) -cne $identity){throw '员工快捷方式临时文件身份变化。'}
  }finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($newLink)}
  $reservation.Dispose();$reservation=$null
  $tempPin=Pin-PlainFile $temp
  try{if([XjyEmployeeShortcutIo]::Identity($tempPin.SafeFileHandle) -cne $identity){throw '员工快捷方式临时文件被替换。'};Assert-XjyEmployeeLink $shell $temp $targetExe $install;$contentSha=File-Hash $tempPin}finally{$tempPin.Dispose()}
  if([XjyEmployeeShortcutIo]::Identity($desktopPin) -cne $desktopIdentity){throw '员工桌面目录身份变化。'}
  [XjyEmployeeShortcutIo]::Publish($temp,$path,$identity,$contentSha)
  $final=Pin-PlainFile $path;$pins.Add($final)
  if([XjyEmployeeShortcutIo]::Identity($final.SafeFileHandle) -cne $identity -or (File-Hash $final) -cne $contentSha){throw '员工快捷方式发布读回身份或字节不符。'}
  Assert-XjyEmployeeLink $shell $path $targetExe $install
  return [pscustomobject]@{created=$true;reused=$false;path=$path}
 }finally{if($reservation){$reservation.Dispose()};if($shell){[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($shell)};for($i=$pins.Count-1;$i -ge 0;$i--){$pins[$i].Dispose()}}
}
function Complete-XjyEmployeeShortcut($Result){
 if(!$Result -or $Result.completed -isnot [bool] -or $Result.completed -ne $true -or $Result.role -cne 'employee' -or $Result.version -cne '1.7.0' -or $Result.engineVersion -cne '44.9.0'){throw '员工程序尚未真实完成，未创建桌面入口。'}
 try{return Ensure-XjyEmployeeShortcut -InstallationDir ([string]$Result.installationDir)}catch{throw ('员工程序已提交，但桌面入口未完成；请保留程序，不要覆盖重装。'+$_.Exception.Message)}
}
try{
 $root=[IO.Path]::GetFullPath($PackageRoot).TrimEnd('\')
 if(!$root.StartsWith([IO.Path]::GetPathRoot($root)) -or $root.StartsWith('\\') -or $root.Substring(2).Contains(':')){throw '请从普通本地目录解压后安装。'}
 Hold-Parents $root
 $rows=([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))|ConvertFrom-Json
 $expected=New-Object 'Collections.Generic.Dictionary[string,object]' ([StringComparer]::OrdinalIgnoreCase)
 foreach($row in $rows){$expected.Add([string]$row.path,$row)}
 $progressView=New-XjyProgressView -Stage '正在检查升级文件' -Detail '正在核对完整安装材料，请保持窗口打开。'
 $progressView.Form.Show();[Windows.Forms.Application]::DoEvents()
 $seen=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
 $dynamicCount=0
 $stack=New-Object 'Collections.Generic.Stack[string]';$stack.Push($root)
 while($stack.Count){$dir=$stack.Pop();foreach($item in Get-ChildItem -LiteralPath $dir -Force){
  if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw '安装包不能经过链接或重解析点。'}
  $relative=$item.FullName.Substring($root.Length+1).Replace('\','/')
  if($relative -in @('engine-bridge-handoff.json','engine-bridge-accepted.json')){
   if($Action -cne 'Bridge' -or $item.PSIsContainer -or $expected.ContainsKey($relative) -or !$seen.Add($relative)){throw '动态桥接记录范围或类型不正确。'}
   $dynamicPin=Pin-PlainFile $item.FullName;try{if($dynamicPin.Length -gt 16384){throw '桥接记录过大。'}}finally{$dynamicPin.Dispose()}
   # HMAC and stable re-reading belong to the native verifier. Do not retain
   # this read handle: a previous ACK must remain atomically replaceable.
   $dynamicCount++;continue
  }
  if($item.PSIsContainer){Hold-Parents $item.FullName;$stack.Push($item.FullName);continue}
  if(!$seen.Add($relative)){throw '安装包含重复名称。'}
  $pin=Pin-PlainFile $item.FullName;$held.Add($pin)
  if($relative -in @('一键升级.cmd','首次安装主机.cmd','首次安装员工.cmd','员工一键升级.cmd','安装组件/native-delivery-170.ps1')){continue}
  if(!$expected.ContainsKey($relative)){throw ('安装包含额外文件：'+$relative)}
  $spec=$expected[$relative]
  if($pin.Length -ne [long]$spec.size -or (File-Hash $pin) -cne [string]$spec.sha256){throw ('安装文件校验未通过：'+$relative)}
  Set-XjyProgressView -View $progressView -Detail ('正在核对：'+$relative)
 }}
 foreach($name in $expected.Keys){if(!$seen.Contains($name)){throw ('安装文件缺失：'+$name)}}
 if($seen.Count -ne $expected.Count+5+$dynamicCount){throw '完整安装包的文件数量不符。'}
 # Fixed build-time helper body; the standalone helper stays in the hashed
 # closure. No runtime script-file load under the user's execution policy.
 # delivery-tools/XjyWorkerResult.ps1
# 安装收尾接收器：有界行式读取，不在 worker 退出后等 EOF；严格保留唯一 result/退出码/版本/角色/Recover 语义。
# 由 Native-Delivery-170.ps1 在 @@PROGRESS_VIEW@@ 之后 dot-source 或内嵌。
# 本文件必须保持 UTF-8 **带 BOM**（Windows PowerShell 5.1 对无 BOM 的 .ps1 按 ANSI 解码，中文会破坏解析）。
function Step-XjyLineReader {
    param([System.IO.StreamReader]$Reader, [hashtable]$State, [string]$Key, [System.Collections.Generic.List[string]]$Sink)
    if ($State[$Key + 'Eof']) { return }
    if ($null -eq $State[$Key + 'Task']) {
        try { $State[$Key + 'Task'] = $Reader.ReadLineAsync() } catch { $State[$Key + 'Eof'] = $true; return }
    }
    $task = $State[$Key + 'Task']
    if ($null -eq $task -or -not $task.IsCompleted) { return }
    try {
        $line = $task.Result
        if ($null -eq $line) { $State[$Key + 'Eof'] = $true; $State[$Key + 'Task'] = $null; return }
        $Sink.Add($line)
        $State[$Key + 'Task'] = $null
    } catch {
        $State[$Key + 'Eof'] = $true
        $State[$Key + 'Task'] = $null
    }
}

function Wait-XjyWorkerResult {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][System.Diagnostics.Process]$Process,
        [ValidateSet('FreshOrUpgrade', 'Recover')][string]$ResultKind = 'FreshOrUpgrade',
        [string]$ExpectedVersion = '1.7.0',
        [string]$ExpectedEngineVersion = '44.9.0',
        [string[]]$AllowedRoles = @('host', 'employee'),
        [int]$ProcessTimeoutMs = 180000,
        [switch]$KeepWaitingWhileProcessRuns,
        [int]$PostExitQuietMs = 750,
        [scriptblock]$OnTick
    )
    if ($null -eq $Process) { throw '缺少 worker 进程对象' }
    if (-not $Process.StartInfo.RedirectStandardOutput -or -not $Process.StartInfo.RedirectStandardError) {
        throw 'worker 进程未重定向 stdout/stderr，无法按合同判定'
    }
    if ($ProcessTimeoutMs -le 0) { $ProcessTimeoutMs = 180000 }
    if ($PostExitQuietMs -lt 0) { $PostExitQuietMs = 750 }

    $outLines = New-Object 'System.Collections.Generic.List[string]'
    $errLines = New-Object 'System.Collections.Generic.List[string]'
    $state = @{ OutTask = $null; ErrTask = $null; OutEof = $false; ErrEof = $false }
    $watch = [System.Diagnostics.Stopwatch]::StartNew()
    $timedOut = $false
    $exitAtMs = -1

    while (-not $Process.HasExited) {
        Step-XjyLineReader -Reader $Process.StandardOutput -State $state -Key 'Out' -Sink $outLines
        Step-XjyLineReader -Reader $Process.StandardError -State $state -Key 'Err' -Sink $errLines
        if ($OnTick) { try { & $OnTick } catch { } }
        if ($watch.ElapsedMilliseconds -ge $ProcessTimeoutMs -and -not $KeepWaitingWhileProcessRuns) { $timedOut = $true; break }
        Start-Sleep -Milliseconds 20
    }
    if (-not $timedOut) { $exitAtMs = $watch.ElapsedMilliseconds }

    if ($timedOut) {
        return [pscustomobject]@{
            Phase = 'FailProcessTimeout'; ExitCode = $null; Result = $null
            Stdout = ($outLines -join "`n"); Stderr = ($errLines -join "`n")
            Reason = ('worker 在 ' + $ProcessTimeoutMs + ' 毫秒内未退出；未结束进程，保留现场')
            ExitAtMs = -1; EofObserved = ($state.OutEof -and $state.ErrEof)
        }
    }

    [void]$Process.WaitForExit()
    $exitCode = $Process.ExitCode
    $quiet = [System.Diagnostics.Stopwatch]::StartNew()
    $last = $outLines.Count + $errLines.Count
    while ($quiet.ElapsedMilliseconds -lt $PostExitQuietMs) {
        Step-XjyLineReader -Reader $Process.StandardOutput -State $state -Key 'Out' -Sink $outLines
        Step-XjyLineReader -Reader $Process.StandardError -State $state -Key 'Err' -Sink $errLines
        $now = $outLines.Count + $errLines.Count
        if ($now -ne $last) { $last = $now; $quiet.Restart() }
        if ($state.OutEof -and $state.ErrEof) { break }
        if ($OnTick) { try { & $OnTick } catch { } }
        Start-Sleep -Milliseconds 20
    }
    $eof = ($state.OutEof -and $state.ErrEof)
    $stdout = (($outLines -join "`n")).TrimStart([char]0xFEFF)
    $stderr = ($errLines -join "`n")

    if ($exitCode -ne 0) {
        return [pscustomobject]@{
            Phase = 'FailExitCode'; ExitCode = $exitCode; Result = $null
            Stdout = $stdout; Stderr = $stderr
            Reason = ('worker 退出码为 ' + $exitCode + '，不等于 0')
            ExitAtMs = $exitAtMs; EofObserved = $eof
        }
    }

    $results = New-Object 'System.Collections.Generic.List[object]'
    $parseReason = $null
    foreach ($line in @($stdout -split "\r?\n")) {
        $text = $line.Trim()
        if ($text.Length -eq 0) { continue }
        $value = $null
        try { $value = ConvertFrom-Json -InputObject $text } catch { $parseReason = 'stdout 含无法解析为 JSON 的行'; break }
        if ($null -eq $value) { $parseReason = 'stdout 含空 JSON 值'; break }
        $type = $value.PSObject.Properties['type']
        if ($null -eq $type -or ([string]$type.Value) -cne 'result') { continue }
        $results.Add($value)
    }
    if ($null -eq $parseReason -and $results.Count -ne 1) { $parseReason = '维护助手没有返回唯一完成记录' }
    if ($null -ne $parseReason) {
        return [pscustomobject]@{
            Phase = 'FailResult'; ExitCode = $exitCode; Result = $null
            Stdout = $stdout; Stderr = $stderr; Reason = $parseReason
            ExitAtMs = $exitAtMs; EofObserved = $eof; ResultCount = $results.Count
        }
    }

    $result = $results[0]
    $fieldReason = $null
    if ($ResultKind -eq 'Recover') {
        $p = $result.PSObject.Properties['recovered']
        if ($null -eq $p) { $fieldReason = 'recovered 缺失' }
        elseif (-not ($p.Value -is [bool])) { $fieldReason = 'recovered 不是布尔值' }
        elseif ($p.Value -ne $true) { $fieldReason = '恢复未获确认' }
    } else {
        $p = $result.PSObject.Properties['completed']
        if ($null -eq $p) { $fieldReason = 'completed 缺失' }
        elseif (-not ($p.Value -is [bool])) { $fieldReason = 'completed 不是布尔值' }
        elseif ($p.Value -ne $true) { $fieldReason = 'completed 不为 true' }
        elseif ($null -eq $result.PSObject.Properties['version'] -or $result.version -isnot [string] -or ([string]$result.version) -cne $ExpectedVersion) { $fieldReason = 'version 不符' }
        elseif ($null -eq $result.PSObject.Properties['engineVersion'] -or $result.engineVersion -isnot [string] -or ([string]$result.engineVersion) -cne $ExpectedEngineVersion) { $fieldReason = 'engineVersion 不符' }
        elseif ($null -eq $result.PSObject.Properties['role'] -or $result.role -isnot [string] -or $AllowedRoles -notcontains ([string]$result.role)) { $fieldReason = 'role 不符' }
    }
    if ($null -ne $fieldReason) {
        return [pscustomobject]@{
            Phase = 'FailResult'; ExitCode = $exitCode; Result = $result
            Stdout = $stdout; Stderr = $stderr; Reason = $fieldReason
            ExitAtMs = $exitAtMs; EofObserved = $eof; ResultCount = 1
        }
    }
    return [pscustomobject]@{
        Phase = 'Success'; ExitCode = $exitCode; Result = $result
        Stdout = $stdout; Stderr = $stderr; Reason = ''
        ExitAtMs = $exitAtMs; EofObserved = $eof; ResultCount = 1
    }
}

 if($Action -ceq 'Bridge' -and !(Test-Path -LiteralPath (Join-Path $root 'engine-bridge-handoff.json') -PathType Leaf)){throw '原员工更新的认证交接记录缺失。'}
 $mode=switch($Action){'Upgrade'{'--upgrade'};'FreshHost'{'--fresh-host'};'FreshEmployee'{'--fresh-employee'};'Recover'{'--recover'};'RecoverStart'{'--recover-start'};'Bridge'{'--continue-bridge'};'EmployeeSlot'{'--employee-slot'};'EmployeeSlotRecover'{'--employee-slot-recover'}}
