 # Keep source handles held until this worker really exits; slow copying is not a failed install.
 $outcome=Wait-XjyWorkerResult -Process $p -ResultKind $resultKind -ExpectedVersion '1.7.0' -ExpectedEngineVersion '44.9.0' -AllowedRoles $allowedRoles -KeepWaitingWhileProcessRuns -OnTick {
  $elapsedSeconds=[int][Math]::Floor($workerWatch.Elapsed.TotalSeconds)
  if($elapsedSeconds -ne $workerViewState.LastSecond){
   $workerViewState.LastSecond=$elapsedSeconds
   $minutes=[int][Math]::Floor($elapsedSeconds/60);$seconds=$elapsedSeconds%60
   Set-XjyProgressView -View $progressView -Detail ('正在安装及校验，已用 '+$minutes+' 分 '+$seconds+' 秒。请不要重复运行；完成后会明确提示结果。')
  }
  [Windows.Forms.Application]::DoEvents()
 }
 if($outcome.Phase -cne 'Success'){throw ('安装或升级未确认完成。请保留原程序、备份和错误记录。'+"`n"+$outcome.Reason+"`n"+$outcome.Stderr)}
 $result=$outcome.Result
 if($Action -in @('Recover','RecoverStart','EmployeeSlotRecover')){if($result.recovered -ne $true){throw '恢复未获确认，请保留现场。'}}else{if($result.completed -ne $true -or $result.version -cne '1.7.0' -or $result.engineVersion -cne '44.9.0' -or $result.role -cnotin @('host','employee')){throw '完整安装或正确角色启动未获确认，请保留原始记录。'}}
 if($Action -in @('EmployeeSlot','EmployeeSlotRecover') -and ($null -eq $result.PSObject.Properties['role'] -or $result.role -isnot [string] -or $result.role -cne 'employee')){throw '员工slot结果角色不符，请保留现场。'}
 $wrapperEmployeeShortcut=$null
 if($Action -notin @('Recover','RecoverStart','EmployeeSlotRecover') -and $result.role -ceq 'employee' -and $result.completed -eq $true){$wrapperEmployeeShortcut=Complete-XjyEmployeeShortcut $result}
 Close-XjyProgressView -View $progressView
 $note='处理结果已确认。请在打开的软件中核对版本和角色；员工连接店内主机后登录。'
 if($Action -ceq 'EmployeeSlotRecover'){$note='员工slot的认证恢复处理已确认，原程序和原资料保留。请按恢复结果重新打开原员工程序，或重新运行员工补丁继续；恢复成功不代表新slot已经切换。'}
