 if($null -ne $wrapperEmployeeShortcut){if($wrapperEmployeeShortcut.created -eq $true){$note+=' 员工桌面快捷方式已创建。'}elseif($wrapperEmployeeShortcut.reused -eq $true){$note+=' 员工桌面快捷方式已复用。'}}
 if($null -ne $shortcutProperty){$shortcut=$shortcutProperty.Value;$shortcutError=$shortcut.PSObject.Properties['error'];if($null -ne $shortcutError){throw ('程序已提交，但桌面快捷方式未完成：'+[string]$shortcutError.Value)};if($shortcut.created -eq $true){$note+=' 桌面快捷方式已创建。'}elseif($shortcut.reused -eq $true){$note+=' 桌面快捷方式已复用。'}}
 $done=$null;try{$done=New-XjyProgressView -Stage '鑫金源珠宝 1.7 更新已完成' -Detail $note;$done.Form.Show();$sw=[Diagnostics.Stopwatch]::StartNew();while($sw.Elapsed.TotalSeconds -lt 2.5){[Windows.Forms.Application]::DoEvents();Start-Sleep -Milliseconds 50}}catch{[Console]::Error.WriteLine('WARNING: 处理结果已确认，但成功提示显示失败：'+$_.Exception.Message)}finally{try{Close-XjyProgressView -View $done}catch{[Console]::Error.WriteLine('WARNING: 处理结果已确认，但成功提示窗口关闭失败：'+$_.Exception.Message)}}
 exit 0
}catch{$failureMessage=$_.Exception.Message;[Console]::Error.WriteLine($failureMessage);Close-XjyProgressView -View $progressView;[void][Windows.Forms.MessageBox]::Show($failureMessage,'安装或升级未完成',[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Error);exit 1}
finally{Close-XjyProgressView -View $progressView;for($i=$held.Count-1;$i -ge 0;$i--){$held[$i].Dispose()}}
